    ori=None
    for r in range(h):
        if len(set(g[r]))==1 and g[r][0]!=0:
            L=r; ori='h'; col=g[r][0]; break
    if ori is None:
        for c in range(w):
            if len(set(g[r][c] for r in range(h)))==1 and g[0][c]!=0:
                L=c; ori='v'; col=g[0][c]; break
